let palette = ['#7B62A3', '#7fc8f8', '#ffe45e', '#ff6392', '#17bebb', '#f0f0f0'];
let ctx;
let centerX, centerY;
let windows = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	background('#000000');
}

function draw() {
	drawBackground(centerX, centerY, width, 100);
	for (let w of windows) {
		w.run();
	}

	if (frameCount < 60) {
		if (frameCount % 3 == 0) {
			let w = random(0.1, 0.6) * width;
			let h = random(0.1, 0.6) * height;
			let x = random(width - w) + w / 2;
			let y = random(height - h) + h / 2;
			windows.push(new Window(x, y, w, h));
		}
	}
}

function drawBackground(x, y, w, cellCount) {
	let cellW = w / cellCount;
	noStroke();
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = j * cellW + cellW / 2 + x - (w / 2);
			let cellY = i * cellW + cellW / 2 + y - (w / 2);
			let clr = '#444444'
			if ((i + j) % 2 == 0) {
				clr = '#5a5a5a'
			}
			fill(clr);
			rect(cellX, cellY, cellW);
		}
	}
}

function mouseClicked() {
	for (let i = 0; i < windows.length; i++) {
		let w = windows[i];
		if (w.isMouseOverCloseIcon((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))) {
			windows.splice(i, 1);
			return;
		}
	}
}

function easeInOutQuad(x) {
	return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
}

/*------------------------------------------------------------------------------------------*/


class Window {
	constructor(x, y, w, h) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.corner = width * 0.008;
		this.shadowOffset = width * 0.004;
		this.thickness = width / 700;
		this.barH = width * 0.028;
		this.barY = (this.barH - this.h) / 2;
		this.iconSize = width * 0.017;
		this.isClosed = false;


		this.timer = 0;
		this.openProgress = 0;
		this.openingTime = 30;

		this.palette = palette.slice();
		shuffle(this.palette, true);
		this.iconClr = this.palette[0];
		this.barClr = this.palette[1];
		this.bgClr = '#F9F4E7';
		this.stClr = '#000000';
	}

	show() {
		this.closeIconX = (this.w / 2) - (this.barH / 2);

		push();
		translate(this.x, this.y);
		scale(this.openProgress);
		noStroke();
		fill('#000');
		rect(this.shadowOffset, this.shadowOffset, this.w, this.h, this.corner);
		stroke('#000');
		strokeWeight(this.thickness);
		fill(this.bgClr);
		rect(0, 0, this.w, this.h, this.corner);
		fill(this.barClr);
		rect(0, this.barY, this.w, this.barH, this.corner, this.corner, 0, 0);
		fill(this.iconClr);
		this.drawCloseIcon(this.closeIconX, this.barY, this.iconSize);
		this.drawMaximizeIcon((this.w / 2) - (this.barH / 2) * 2.75, this.barY, this.iconSize);
		this.drawMinimizeIcon((this.w / 2) - (this.barH / 2) * 4.5, this.barY, this.iconSize);
		pop();
	}

	update() {
		if (this.timer < this.openingTime) {
			let nrm = norm(this.timer, 0, this.openingTime - 1);
			this.openProgress = lerp(0, 1, easeInOutQuad(nrm));
		}
		this.timer++;
	}

	isMouseOverCloseIcon(mx, my) {
		const iconX = this.closeIconX;
		const iconY = this.barY;
		const halfSize = this.iconSize / 2;

		const relativeMX = mx - this.x;
		const relativeMY = my - this.y;

		return (
			relativeMX > (iconX - halfSize) &&
			relativeMX < (iconX + halfSize) &&
			relativeMY > (iconY - halfSize) &&
			relativeMY < (iconY + halfSize)
		);
	}

	drawCloseIcon(x, y, w) {
		push();
		translate(x, y);
		square(0, 0, w, w * 0.25);
		line(-w * 0.3, -w * 0.3, w * 0.3, w * 0.3);
		line(w * 0.3, -w * 0.3, -w * 0.3, w * 0.3);
		pop();
	}

	drawMaximizeIcon(x, y, w) {
		push();
		translate(x, y);
		square(0, 0, w, w * 0.25);
		square(0, 0, w * 0.5);
		line(-w * 0.25, -w * 0.175, w * 0.25, -w * 0.175);
		pop();
	}

	drawMinimizeIcon(x, y, w) {
		push();
		translate(x, y);
		square(0, 0, w, w * 0.1);
		line(-w * 0.25, w * 0.175, w * 0.25, w * 0.175);
		pop();
	}

	run() {
		this.show();
		this.update();
	}
}

